package br.com.cineo;
import android.app.*;import android.content.*;import android.widget.*;import android.view.*;import android.text.*;import org.json.*;import java.util.*;import java.net.URLEncoder;import static br.com.cineo.MainActivity.*;
/** Viewer library, discovery and the grouped inbox live outside the compact profile. */
class LibraryHub {
 final MainActivity a;JSONObject settings=new JSONObject();int searchVersion=0;String searchTheme="";JSONObject homeBootstrap=new JSONObject();JSONArray recommended=new JSONArray();LibraryHub(MainActivity activity){a=activity;}
 void get(String p,MainActivity.Done d){a.call("GET","/v8"+p,null,d);}void post(String p,JSONObject b,MainActivity.Done d){a.call("POST","/v8"+p,b,d);}void page(String id,String title,String sub){a.page(id,title,sub,2,()->a.profile());}
 void prepareHome(Runnable done){a.call("GET","/v8/bootstrap",null,r->{homeBootstrap=r;applySettings(r);a.call("GET","/v8/library?state=watching",null,rows->{JSONArray values=rows.getJSONArray("items");for(int i=0;i<values.length();i++){JSONObject value=values.getJSONObject(i);a.prefs.edit().putBoolean(a.local("hide_resume_"+value.optInt("id")),value.optBoolean("hide_resume")).apply();}a.call("GET","/v8/recommendations",null,rec->{recommended=rec.getJSONArray("items");done.run();});});});}
 void home(LinearLayout p){JSONArray notices=homeBootstrap.optJSONArray("notices");if(notices!=null)for(int i=0;i<notices.length();i++){JSONObject n=notices.optJSONObject(i);a.title(p,n.optString("title"),18);a.text(p,n.optString("body"),14,MUTED);a.button(p,"Ver aviso",CARD,()->destination(n.optString("destination")));}if(recommended.length()>0){ArrayList<JSONObject> rows=new ArrayList<>();for(int i=0;i<recommended.length();i++)rows.add(recommended.optJSONObject(i));a.shelf(p,"Selecionadas para você",rows,false);a.button(p,"Entender e ajustar recomendações",CARD,()->recommendations());}}
 void destination(String tool){if(tool.equals("support"))a.complete.support();else if(tool.equals("updates"))news();else if(tool.equals("preferences"))a.dashboard.preferences();else if(tool.equals("library"))open("watching");else inbox();}
 void recommendations(){page("controlled-recommendations","Para você","Entenda cada indicação e ajuste seus interesses.");a.button(a.body,"Ajustar recomendações",CARD,()->recommendationSettings());get("/recommendations",r->renderShows(a.body,r.getJSONArray("items"),true));}
 void open(String state){page("library-hub","Sua biblioteca","Suas histórias, do primeiro ao último capítulo.");LinearLayout tabs=a.row();String[] labels={"Assistindo","Concluídas","Pausadas","Seguindo"},values={"watching","completed","abandoned","following"};for(int i=0;i<labels.length;i++){final String value=values[i];Button b=a.button(tabs,labels[i],state.equals(value)?RED:CARD,()->open(value));b.setTextSize(11);b.setPadding(a.dp(3),0,a.dp(3),0);b.setLayoutParams(new LinearLayout.LayoutParams(0,a.dp(44),1));}a.body.addView(tabs);a.button(a.body,"Histórias para terminar hoje",CARD,()->tonight());get("/library?state="+state,r->renderShows(a.body,r.getJSONArray("items"),true));}
 void renderShows(LinearLayout parent,JSONArray rows,boolean options)throws Exception{if(rows.length()==0){a.empty(parent,"film","Nenhuma história nesta área","Explore o catálogo e escolha sua próxima história.");return;}for(int i=0;i<rows.length();i++){JSONObject s=rows.getJSONObject(i);a.showCard(parent,s,"catalog");if(!s.isNull("remaining_seconds")&&s.optInt("remaining_seconds")>0)a.text(parent,"Faltam aproximadamente "+Math.max(1,(s.optInt("remaining_seconds")+59)/60)+" minutos",12,MUTED);if(options)a.button(parent,"Organizar esta história",BG,()->choices(s));}}
 void choices(JSONObject s){new AlertDialog.Builder(a).setTitle(s.optString("title")).setItems(new String[]{"Marcar como concluída","Voltar para assistindo","Deixar para outra hora","Ocultar de Continue assistindo","Não tenho interesse","Por que apareceu para mim?"},(d,n)->{if(n==5){new AlertDialog.Builder(a).setMessage(s.optString("recommendation_reason","Esta história faz parte do catálogo disponível para seu perfil.")).setPositiveButton("Entendi",null).show();return;}a.safe(()->{JSONObject data=a.obj("show_id",s.optInt("id"));if(n<3)data.put("state",new String[]{"completed","watching","abandoned"}[n]);if(n==3)data.put("hide_resume",true);if(n==4)data.put("interested",false);post("/library-choice",data,r->{if(n==3)a.prefs.edit().putBoolean(a.local("hide_resume_"+s.optInt("id")),true).apply();Toast.makeText(a,"Sua biblioteca foi atualizada.",0).show();});});}).show();}
 void tonight(){page("finish-tonight","Termine hoje","Encontre uma história que cabe no seu tempo.");EditText minutes=a.field(a.body,"TEMPO DISPONÍVEL EM MINUTOS","60",false);minutes.setInputType(2);minutes.setText("60");LinearLayout rows=a.col();a.body.addView(rows);a.button(a.body,"Encontrar histórias",RED,()->a.safe(()->{int n=Integer.parseInt(minutes.getText().toString());get("/library?state=tonight&minutes="+n,r->{rows.removeAllViews();renderShows(rows,r.getJSONArray("items"),true);});}));}
 void bookmarks(){page("scene-bookmarks","Cenas salvas","Volte direto aos momentos que você marcou.");get("/bookmarks",r->{JSONArray items=r.getJSONArray("items");if(items.length()==0)a.empty(a.body,"save","Sua coleção de cenas","No player, escolha Salvar cena para marcar um momento.");for(int i=0;i<items.length();i++){JSONObject b=items.getJSONObject(i),e=b.getJSONObject("episode"),s=e.getJSONObject("show");a.title(a.body,b.optString("caption").isEmpty()?s.optString("title"):b.optString("caption"),18);a.text(a.body,e.optString("title")+" · "+a.time(b.optInt("position_ms")),13,MUTED);a.button(a.body,"Assistir deste momento",RED,()->a.call("GET","/shows/"+s.optInt("id")+"/episodes",null,eps->{JSONArray episodes=eps.getJSONArray("items");for(int j=0;j<episodes.length();j++)if(episodes.getJSONObject(j).optInt("id")==e.optInt("id")){a.prefs.edit().putInt(a.local("episode_"+e.optInt("id")),b.optInt("position_ms")).apply();a.play(s,episodes,j,"catalog");return;}a.notice("Este capítulo não está mais disponível.",true);}));a.button(a.body,"Remover marcador",CARD,()->a.safe(()->post("/bookmarks",a.obj("id",b.optString("id"),"remove",true),ok->bookmarks())));}});}
 void saveScene(){if(!a.drama.active||!a.drama.publicEpisode()||a.video==null)return;final int eid=a.playingEpisode,position=a.video.getCurrentPosition();EditText label=new EditText(a);label.setHint("Nome da cena · opcional");label.setFilters(new InputFilter[]{new InputFilter.LengthFilter(100)});new AlertDialog.Builder(a).setTitle("Salvar cena · "+a.time(position)).setView(label).setNegativeButton("Cancelar",null).setPositiveButton("Salvar",(d,n)->a.safe(()->post("/bookmarks",a.obj("episode_id",eid,"position_ms",position,"caption",label.getText().toString()),r->Toast.makeText(a,"Cena salva na sua biblioteca.",0).show()))).show();}
 void calendar(){page("personal-calendar","Seu calendário","Próximos capítulos das histórias que você acompanha.");get("/calendar",r->{JSONArray rows=r.getJSONArray("items");if(rows.length()==0)a.empty(a.body,"calendar","Sem estreias agendadas","Acompanhe séries e criadores para organizar seus próximos capítulos.");for(int i=0;i<rows.length();i++){JSONObject e=rows.getJSONObject(i),s=e.getJSONObject("show");a.title(a.body,s.optString("title"),18);a.text(a.body,e.optString("title")+"\n"+a.pro.date(e.optString("at")),14,MUTED);}});}
 void inbox(){page("unified-inbox","Seus avisos","Episódios, correções e atendimento organizados.");get("/inbox",r->{JSONArray groups=r.getJSONArray("groups");if(groups.length()==0)a.empty(a.body,"bell","Tudo em dia","As novidades das suas histórias aparecerão aqui.");for(int i=0;i<groups.length();i++){JSONObject g=groups.getJSONObject(i);a.title(a.body,g.optString("title")+(g.optInt("unread")>0?" · "+g.optInt("unread")+" novo(s)":""),19);JSONArray items=g.getJSONArray("items");for(int j=0;j<items.length();j++){JSONObject e=items.getJSONObject(j);a.text(a.body,(e.optBoolean("read")?"":"• ")+e.optString("body"),14,e.optBoolean("read")?MUTED:WHITE);}a.button(a.body,"Marcar grupo como lido",CARD,()->a.safe(()->{JSONArray keys=new JSONArray();for(int j=0;j<items.length();j++)keys.put(items.getJSONObject(j).getString("key"));post("/inbox",a.obj("keys",keys),ok->inbox());}));if(g.optInt("show_id")>0)a.button(a.body,"Abrir série",BG,()->a.loadDetail(g.optInt("show_id"),"catalog"));}});}
 void news(){page("release-news","Novidades do Cineo","Versão instalada: 0.8.0");get("/news",r->{JSONArray rows=r.getJSONArray("items");if(rows.length()==0)a.text(a.body,"As notas das versões publicadas aparecerão aqui.",14,MUTED);for(int i=0;i<rows.length();i++){JSONObject v=rows.getJSONObject(i);a.title(a.body,v.optString("title"),21);JSONArray items=v.optJSONArray("items");if(items!=null)for(int j=0;j<items.length();j++){JSONObject item=items.getJSONObject(j);a.title(a.body,item.optString("title"),16);a.text(a.body,item.optString("body"),14,MUTED);for(ProfileDashboard.Tool tool:a.dashboard.tools())if(tool.id.equals(item.optString("tool")))a.button(a.body,"Abrir "+tool.title,CARD,tool.run);}if(v.optInt("version")>8&&!v.optString("download_url").isEmpty())a.button(a.body,"Baixar atualização",RED,()->a.startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(v.optString("download_url")))));}});}
 void viewingSettings(){page("viewing-choices","Tempo e gestos","");get("/preferences",r->{settings=r;EditText minutes=a.field(a.body,"LEMBRETE DE MARATONA EM MINUTOS","0 = desativado",false);minutes.setInputType(2);minutes.setText(String.valueOf(r.optInt("watch_minutes")));Spinner orientation=a.select(a.body,"ORIENTAÇÃO PREFERIDA",new String[]{"Automática","Retrato","Paisagem"},r.optString("orientation").equals("landscape")?"Paisagem":r.optString("orientation").equals("portrait")?"Retrato":"Automática");CheckBox gesture=new CheckBox(a);gesture.setText("Exigir um deslize maior para trocar de capítulo");gesture.setTextColor(WHITE);gesture.setChecked(r.optBoolean("sensitive_swipe"));a.body.addView(gesture);a.button(a.body,"Salvar preferências",RED,()->a.safe(()->post("/preferences",a.obj("watch_minutes",Integer.parseInt(minutes.getText().toString()),"orientation",new String[]{"auto","portrait","landscape"}[orientation.getSelectedItemPosition()],"sensitive_swipe",gesture.isChecked(),"revision",settings.optInt("revision")),ok->{applySettings(ok);a.notice("Preferências salvas.",false);})));});}
 void recommendationSettings(){page("recommendation-settings","Suas recomendações","");a.button(a.body,"Escolher gêneros favoritos",CARD,()->a.complete.preferences(false));get("/preferences",r->{CheckBox hide=new CheckBox(a);hide.setText("Evitar recomendar séries já concluídas");hide.setTextColor(WHITE);hide.setChecked(r.optBoolean("hide_completed"));a.body.addView(hide);a.button(a.body,"Salvar preferência",RED,()->a.safe(()->post("/preferences",a.obj("hide_completed",hide.isChecked(),"revision",r.optInt("revision")),ok->a.notice("Preferência salva.",false))));a.button(a.body,"Reconsiderar histórias ocultadas",CARD,()->new AlertDialog.Builder(a).setTitle("Reiniciar indicações de interesse?").setMessage("As histórias marcadas como Não tenho interesse poderão voltar às recomendações.").setNegativeButton("Cancelar",null).setPositiveButton("Reiniciar",(d,n)->post("/reset-recommendations",new JSONObject(),ok->a.notice("Indicações reiniciadas.",false))).show());});}
 void applySettings(JSONObject r){a.prefs.edit().putInt(a.local("watch_minutes"),r.optInt("watch_minutes")).putString(a.local("orientation"),r.optString("orientation","auto")).putBoolean(a.local("sensitive_swipe"),r.optBoolean("sensitive_swipe")).apply();}
 void surveys(){page("satisfaction-surveys","Sua opinião","Ajude a escolher as próximas melhorias.");get("/surveys",r->{JSONArray rows=r.getJSONArray("items");if(rows.length()==0)a.empty(a.body,"chat","Nenhuma pesquisa aberta","Novas pesquisas aparecerão quando a equipe publicar.");for(int i=0;i<rows.length();i++){JSONObject p=rows.getJSONObject(i);a.title(a.body,p.optString("question"),20);JSONArray options=p.getJSONArray("options");for(int j=0;j<options.length();j++){final int choice=j;a.button(a.body,options.getString(j),CARD,()->a.safe(()->post("/surveys",a.obj("vote",true,"id",p.optString("id"),"choice",choice),ok->Toast.makeText(a,"Obrigado! Sua resposta foi registrada.",0).show())));}}});}
 void search(){a.page("catalogue-search","Encontre sua história","Títulos, criadores e temas. Até com pequenos erros de digitação.",1,()->a.catalog(false));EditText query=a.field(a.body,"","O que você quer assistir?",false);EditText theme=a.field(a.body,"TEMA OPCIONAL","Ex.: família, mistério, corridas",false);a.button(a.body,"Abrir filtros avançados",CARD,()->a.complete.discovery());LinearLayout results=a.col();a.body.addView(results);final int page=a.generation;Runnable[] pending={null};TextWatcher watcher=new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int after){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int st,int before,int count){if(pending[0]!=null)a.handler.removeCallbacks(pending[0]);final int sequence=++searchVersion;pending[0]=()->{if(page!=a.generation)return;try{String value=URLEncoder.encode(query.getText().toString(),"UTF-8");a.socialRequest("GET","/v8/search?q="+value+"&theme="+android.net.Uri.encode(theme.getText().toString().trim()),null,r->{if(sequence!=searchVersion)return;results.removeAllViews();if(r.optBoolean("approximate"))a.text(results,"Encontramos títulos com nomes parecidos.",13,AMBER);renderShows(results,r.getJSONArray("items"),false);});}catch(Exception ex){a.notice("Não foi possível buscar agora.",true);}};a.handler.postDelayed(pending[0],350);}};query.addTextChangedListener(watcher);theme.addTextChangedListener(watcher);watcher.onTextChanged("",0,0,0);}
 void detail(LinearLayout p,JSONObject s){if(!s.optString("status").equals("approved"))return;a.button(p,"Organizar na minha biblioteca",CARD,()->choices(s));a.button(p,"Enquetes desta história",CARD,()->polls(s));JSONArray warnings=s.optJSONArray("warnings");if(warnings!=null&&warnings.length()>0){a.title(p,"Avisos de conteúdo",16);for(int i=0;i<warnings.length();i++)a.text(p,warnings.optString(i),13,AMBER);}String life=s.optString("lifecycle");if(!life.isEmpty())a.text(p,life.equals("complete")?"História completa":life.equals("paused")?"Publicação pausada":"Novos capítulos em andamento",13,MUTED);}
 void polls(JSONObject s){page("show-polls",s.optString("title"),"Enquetes publicadas pelo criador.");get("/polls/"+s.optInt("id"),r->{JSONArray rows=r.getJSONArray("items");if(rows.length()==0)a.empty(a.body,"chat","Ainda sem enquetes","As perguntas do criador aparecerão aqui.");for(int i=0;i<rows.length();i++){JSONObject poll=rows.getJSONObject(i);a.title(a.body,poll.optString("question"),20);boolean closed=java.time.Instant.parse(poll.optString("closes_at")).isBefore(java.time.Instant.now());JSONArray options=poll.getJSONArray("options"),counts=poll.optJSONArray("counts");for(int j=0;j<options.length();j++){final int choice=j;String label=options.getString(j)+" · "+(counts==null?0:counts.optInt(j))+" voto(s)";Button b=a.button(a.body,label,CARD,()->a.safe(()->post("/polls/"+s.optInt("id"),a.obj("vote",true,"poll_id",poll.optString("id"),"choice",choice),ok->polls(s))));b.setEnabled(!closed);}a.text(a.body,closed?"Enquete encerrada":"Até "+a.pro.date(poll.optString("closes_at")),12,MUTED);}});}
}
